const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const changes = (entry.changes && entry.changes[0]) || {};
const value = changes.value || {};
const message = (value.messages && value.messages[0]) || {};
const contact = (value.contacts && value.contacts[0]) || {};

const customerPhone = message.from || value.metadata?.display_phone_number || '+6590000000';
const customerName = contact.profile?.name || 'Valued Customer';
const messageText = message.text?.body || '';
const messageId = message.id || 'MSG_' + Date.now();
const messageType = message.type || 'text';

return {
  json: {
    sessionId: customerPhone,
    customerPhone: customerPhone,
    customerName: customerName,
    messageText: messageText,
    messageId: messageId,
    messageType: messageType,
    receivedAt: new Date().toISOString(),
    subtask: 'SUBTASK_1_INGESTION_AND_INTENT'
  }
};

const agentOutput = $input.first().json.output || 'Hello! Welcome to Union Gas. How can we assist you with your LPG gas supply today?';
const customerPhone = $('2. Inbound Message Parser').first().json.customerPhone;

return {
  json: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: customerPhone,
    type: 'text',
    text: {
      body: agentOutput
    },
    subtaskCompleted: 'SUBTASK_1'
  }
};
